<script setup lang="ts">
import { ui } from "../ui"
import DateTime from './DateTime.vue'
import type { Check } from '../types'
defineProps<{ checks: Check[] }>()
</script>
<template><div :class="ui('$all', '$div', 'table-scroll health-table')" tabindex="0" role="region" aria-label="Health checks and dated observations"><table :class="ui('$all', '$table')"><caption :class="ui('$all', '$caption', 'sr-only')">Monitoring health checks</caption><thead :class="ui('$all', '$thead')"><tr :class="ui('$all', '$tr')"><th scope="col" :class="ui('$all', '$th')">Check</th><th scope="col" :class="ui('$all', '$th')">Evidence</th><th scope="col" :class="ui('$all', '$th')">Result</th></tr></thead><tbody :class="ui('$all', '$tbody')"><tr :class="ui('$all', '$tr')" v-for="check in checks" :key="check.key"><td :class="ui('$all', '$td')"><strong :class="ui('$all', '$strong')">{{ check.label }}</strong><p :class="ui('$all', '$p', 'help')">{{ check.detail }}</p><div v-if="check.kind!=='configuration'" :class="ui('$all', '$div', 'health-times')"><small :class="ui('$all', '$small')" v-if="check.last_started_at">Started <DateTime :class="ui('$all', '$DateTime')" :value="check.last_started_at"/></small><small :class="ui('$all', '$small')" v-if="check.last_success_at">Succeeded <DateTime :class="ui('$all', '$DateTime')" :value="check.last_success_at"/></small><small :class="ui('$all', '$small')" v-if="check.last_failure_at">Failed <DateTime :class="ui('$all', '$DateTime')" :value="check.last_failure_at"/></small><small :class="ui('$all', '$small')" v-if="!check.last_started_at&&!check.last_success_at&&!check.last_failure_at"><template v-if="check.observed_at">Observed <DateTime :class="ui('$all', '$DateTime')" :value="check.observed_at"/></template><template v-else>No dated processing observation</template></small></div></td><td :class="ui('$all', '$td', 'quiet')">{{ check.kind === 'configuration' ? 'Configuration' : 'Observation' }}</td><td :class="ui('$all', '$td')"><span :class="ui('$all', '$span', 'badge', (check.state))" >{{ check.state === 'running'?'Started':check.state === 'passed' ? 'Passed' : check.state === 'warning' ? 'Warning' : check.state === 'failed' ? 'Failed' : 'Unverified' }}</span></td></tr></tbody></table></div></template>
